package mz.bam.seeky.android;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.*;

/** No background poller: refreshes when reading state changes or the launcher requests it. */
public final class ReadingWidget extends AppWidgetProvider {
    static void pin(android.app.Activity a){AppWidgetManager manager=AppWidgetManager.getInstance(a);if(manager.isRequestPinAppWidgetSupported())manager.requestPinAppWidget(new ComponentName(a,ReadingWidget.class),null,null);else PlusUi.toast(a,"Mantenha premido o ecrã inicial e adicione o widget Seeky.");}
    public void onUpdate(Context c,AppWidgetManager manager,int[] ids){for(int id:ids)render(c,manager,id);}
    static void update(Context c){try{AppWidgetManager m=AppWidgetManager.getInstance(c);int[] ids=m.getAppWidgetIds(new ComponentName(c,ReadingWidget.class));for(int id:ids)render(c,m,id);}catch(RuntimeException ignored){}}
    static void render(Context c,AppWidgetManager m,int id){LastReading.Saved last=LastReading.get(c);RemoteViews views=new RemoteViews(c.getPackageName(),R.layout.reading_widget);AppPalette p=AppPalette.of(c);views.setInt(R.id.widget_root,"setBackgroundColor",p.surface);views.setTextColor(R.id.widget_title,p.ink);views.setTextColor(R.id.widget_detail,p.muted);views.setTextColor(R.id.widget_continue,p.accent);views.setTextViewText(R.id.widget_title,last.exists()?last.title:AppLanguage.text(c,"Continuar leitura"));views.setTextViewText(R.id.widget_continue,AppLanguage.text(c,"Continuar leitura"));String detail=AppLanguage.text(c,"Abra um livro para começar");if(last.exists()){int part=c.getSharedPreferences("seeky",0).getInt((last.mime.equals("application/pdf")?"reader_page_":"reader_chapter_")+last.uri,0);detail=AppLanguage.text(c,last.mime.equals("application/pdf")?"Página":"Parte")+" "+(part+1);}views.setTextViewText(R.id.widget_detail,detail);Intent open=last.exists()?last.intent(c):new Intent(c,MainActivity.class).putExtra("open_books",true);PendingIntent click=PendingIntent.getActivity(c,id,open.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);views.setOnClickPendingIntent(R.id.widget_root,click);m.updateAppWidget(id,views);}
}
